/// A message from the host: the websocket's binary frames, BLE's `state` characteristic. Throws unless `bytes` is exactly one Envelope.
public func decodeEnvelope(_ bytes: [UInt8]) throws -> Envelope {
    var r = PostcardReader(bytes)
    let v = try Envelope(from: &r)
    try r.done()
    return v
}

/// A message from the host: the websocket's binary frames, BLE's `state` characteristic.
public func encodeEnvelope(_ value: Envelope) -> [UInt8] {
    var w = PostcardWriter()
    value.encode(to: &w)
    return w.bytes
}

