    var r = PostcardReader(bytes)
    let v = try HostEvent(from: &r)
    try r.done()
    return v
}

/// A message to the host: the websocket's binary frames, BLE's `event` characteristic.
public func encodeHostEvent(_ value: HostEvent) -> [UInt8] {
    var w = PostcardWriter()
    value.encode(to: &w)
    return w.bytes
}

